  manifest.runtime.interfaces.capabilities = 1;
  await writeFile(join(dir, "manifest.json"), JSON.stringify(manifest));
  return ArtifactHost.open({ artifact: await loadArtifact(dir), stateDir: join(work, "state"), capabilityBindings: bindings, jobIntervalMs: 0 });
}

describe("outbound ledger after an interrupted attempt", () => {
  it("a later invoke with the same key is not refused forever because an attempt stayed 'sending'", async () => {
    const binding: CapabilityBinding = { capability: "invoices.create", version: 1, provider: { applicationId: "books", url }, credential: TOKEN, grant: { id: "g-1" }, timeoutMs: 5_000 };
    const first = await open([binding]);
    hang = true;
    const inFlight = first.call("caps:invoke", { name: "invoices.create", input: { amount: 5 }, idempotencyKey: "k-1" }, { principal, via: "test" }).catch(e => ({ thrown: String(e) }));
    await new Promise(r => setTimeout(r, 300));
    await first.close().catch(() => undefined);
    await inFlight;
    await new Promise(r => setTimeout(r, 1_700));
    hang = false;
    const second = await open([binding]);
    try {
      const retried = await second.call("caps:invoke", { name: "invoices.create", input: { amount: 5 }, idempotencyKey: "k-1" }, { principal, via: "test" });
      const outbound = await second.outbound();
      expect(outbound.map(r => r.state), JSON.stringify(outbound)).not.toContain("sending");
      expect(retried, JSON.stringify(retried)).toMatchObject({ ok: true, value: { outcome: "succeeded" } });
    } finally {
      await second.close();
    }
  }, 20_000);
});
"}
